const assert=require('node:assert/strict');
const {chromium}=require('playwright'),fs=require('fs'),path=require('path');
const root=path.resolve(__dirname,'..'),out=process.env.GUA_SCREENSHOTS||path.join(require('os').tmpdir(),'jingyue-gua-craft');fs.mkdirSync(out,{recursive:true});
(async()=>{const b=await chromium.launch({executablePath:process.env.GUA_CHROMIUM||undefined,args:['--no-sandbox','--disable-dev-shm-usage','--enable-unsafe-swiftshader','--use-gl=angle','--use-angle=swiftshader']});const c=await b.newContext({viewport:{width:390,height:844},serviceWorkers:'block'}),p=await c.newPage(),errors=[];p.on('pageerror',e=>errors.push(e.message));
await p.route('**/*',async route=>{let u=new URL(route.request().url());if(u.origin!=='https://jingyue.uk')return route.abort();let f=path.resolve(root,'.'+decodeURIComponent(u.pathname==='/'?'/index.html':u.pathname));try{const type={'.html':'text/html','.js':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.webp':'image/webp','.png':'image/png','.json':'application/json','.mp3':'audio/mpeg','.ogg':'audio/ogg','.woff2':'font/woff2'}[path.extname(f)]||'application/octet-stream';await route.fulfill({contentType:type,body:fs.readFileSync(f)});}catch(e){await route.fulfill({status:404,body:''});}});
await p.goto('https://jingyue.uk',{waitUntil:'load'});

let room=p.locator('#yijing-screen');await p.evaluate(()=>JYGuaRoom.open('yijing'));assert.equal(await room.locator('[data-mode=yarrow]').getAttribute('aria-pressed'),'true');assert.equal(await room.locator('[data-action=sound]').count(),0);assert.equal(await room.locator('.gw-scene').getAttribute('data-render'),'webgl');
for(const w of [320,390,768]){await p.setViewportSize({width:w,height:844});assert(await room.evaluate(el=>el.scrollWidth<=el.clientWidth+1));}
await p.setViewportSize({width:390,height:844});await room.locator('#yj-q').fill('易經：這次轉職，我應該如何進退？');await room.locator('[data-action=start]').click();assert.equal((await p.evaluate(()=>JYGuaRoom.snapshot('yijing'))).values.length,0);
await room.locator('[data-action=toss]').click();let first=await p.evaluate(()=>JYGuaRoom.snapshot('yijing'));assert.equal(first.part.length,1);assert(first.busy);await p.evaluate(()=>document.querySelector('#yijing-screen [data-action=toss]').click());assert.deepEqual((await p.evaluate(()=>JYGuaRoom.snapshot('yijing'))).part,first.part);await p.evaluate(()=>JYGuaRoom.close());await p.evaluate(()=>JYGuaRoom.open('yijing'));assert.deepEqual((await p.evaluate(()=>JYGuaRoom.snapshot('yijing'))).part,first.part);
await room.locator('[data-action=toss]').click();await room.locator('[data-action=skip]').click();assert.equal((await p.evaluate(()=>JYGuaRoom.snapshot('yijing'))).part.length,2);await room.locator('[data-action=toss]').click();await room.locator('[data-action=skip]').click();let one=await p.evaluate(()=>JYGuaRoom.snapshot('yijing'));assert.equal(one.values.length,1);assert.equal(one.records[0].changes.length,3);assert.equal(one.part.length,0);assert.deepEqual(one.date,first.date);
await p.screenshot({path:out+'/yarrow-casting.png'});await p.emulateMedia({reducedMotion:'reduce'});
for(let i=0;i<15;i++){await room.locator('[data-action=toss]').click();}await room.locator('.gw-result').waitFor();const result=await p.evaluate(()=>JYGuaRoom.snapshot('yijing').result);assert.equal(result.method,'yarrow');assert.equal(result.records.flatMap(r=>r.changes).length,18);assert.deepEqual(result.calendar,first.date);assert((await room.locator('.gw-prompt-area').inputValue()).includes('大衍蓍草'));
await room.locator('[data-action=share]').click();await p.locator('#jysc-dl:enabled').waitFor();await p.screenshot({path:out+'/yijing-share.png'});await p.locator('#jysc-close').click();await room.locator('[data-action=reset]').click();await room.locator('[data-action=start]').click();await room.locator('[data-action=toss]').click();let partial=await p.evaluate(()=>JYGuaRoom.snapshot('yijing'));await room.locator('[data-action=quick]').click();assert.deepEqual((await p.evaluate(()=>JYGuaRoom.snapshot('yijing').result)).records[0].changes[0],partial.part[0]);await p.evaluate(()=>JYGuaRoom.close());
// Real audio is decoded and scheduled; no network after the local samples load.
await p.evaluate(()=>JYGuaRoom.open('liuyao'));room=p.locator('#liuyao-screen');await room.locator('[data-action=sound]').click();await p.waitForFunction(()=>JYGuaAudio.status().loaded);let audio=await p.evaluate(()=>JYGuaAudio.status());assert(audio.duration>.5&&audio.duration<1);assert.equal(audio.state,'running');await room.locator('#ly-q').fill('六爻：這次工作洽談能否順利落實？');await room.locator('[data-action=start]').click();await room.locator('[data-action=toss]').click();assert.equal((await p.evaluate(()=>JYGuaRoom.snapshot('liuyao'))).values.length,1);assert((await p.evaluate(()=>JYGuaAudio.status())).active>0);
await room.locator('[data-action=quick]').click();const ly=await p.evaluate(()=>JYGuaRoom.snapshot('liuyao').result);assert.equal(ly.method,'coins');await room.locator('[data-action=share]').click();await p.locator('#jysc-dl:enabled').waitFor();await p.screenshot({path:out+'/liuyao-share.png'});await p.locator('#jysc-close').click();await p.evaluate(()=>JYGuaRoom.close());assert.equal((await p.evaluate(()=>JYGuaAudio.status())).active,0);
// Actual exported PNGs from this site's renderer, and static twelve-system poster.
for(const [type,data] of [['invite',{}],['yijing',{question:result.question,gua:result,moving:result.movingPositions,cards:[{name:result.original.fullName,pos:'本卦',lines:result.original.lines,moving:result.movingPositions},...(result.hasChange?[{name:result.changed.fullName,pos:'之卦',lines:result.changed.lines,moving:result.movingPositions}]:[])]}],['liuyao',{question:ly.question,gua:ly,moving:ly.movingPositions,cards:[{name:ly.original.fullName,pos:'本卦',lines:ly.original.lines,moving:ly.movingPositions},...(ly.hasChange?[{name:ly.changed.fullName,pos:'之卦',lines:ly.changed.lines,moving:ly.movingPositions}]:[])]}]]){
 const url=await p.evaluate(async ([type,data])=>(await JYShareCard.render(type,data)).toDataURL(),[type,data]);fs.writeFileSync(out+'/'+type+'-card.png',Buffer.from(url.split(',')[1],'base64'));if(type==='invite'&&process.env.GUA_WRITE_POSTER==='1')fs.writeFileSync(root+'/assets/share/invite-12.png',Buffer.from(url.split(',')[1],'base64'));
}
// Context loss must keep the same cast; the static instrument remains usable.
await p.evaluate(()=>JYGuaRoom.open('yijing'));room=p.locator('#yijing-screen');await room.locator('[data-action=reset]').click();await room.locator('[data-action=start]').click();await room.locator('[data-action=toss]').click();let beforeLoss=await p.evaluate(()=>JYGuaRoom.snapshot('yijing'));
await room.locator('canvas').evaluate(c=>{c.getContext('webgl2').getExtension('WEBGL_lose_context').loseContext();});await p.waitForTimeout(100);assert.equal(await room.locator('.gw-scene').getAttribute('data-render'),'fallback');await room.locator('[data-action=quick]').click();assert.deepEqual((await p.evaluate(()=>JYGuaRoom.snapshot('yijing').result)).records[0].changes[0],beforeLoss.part[0]);
assert.deepEqual(errors,[]);console.log('PASS: WebGL scenes, 18 yarrow changes, partial resume, all three widths, real audio decode/play/stop, reduced motion, distinct cards, twelve-tool PNG, context loss.');await b.close();})();
